def strategy(history, rng):
    def robust(hist, r):
        n = len(hist)
        me = [h[0] for h in hist]
        op = [h[1] for h in hist]
        my_c = sum(1 for a in me if a == 'C')
        op_c = sum(1 for a in op if a == 'C')
        if op_c >= n - max(1, n // 10):
            if op[-1] == 'D': return 'D'
            return 'C'
        if op_c <= n // 3:
            if me[-1] == 'D' and op[-1] == 'D': return 'C'
            if op[-1] == 'D': return 'D'
            return 'C'
        last_me = me[-1]
        last_op = op[-1]
        if last_op == 'D':
            if last_me == 'D': return 'C'
            if r.random() < 0.15: return 'C'
            return 'D'
        if n > 85:
            return 'D' if r.random() < 0.35 else 'C'
        return 'C'

    n = len(history)
    if n == 0:
        return 'D'
    if n == 1:
        return 'D'
    if n == 2:
        return 'C'
    if n == 3:
        if history[1][1] == 'D' and history[2][1] == 'C':
            return 'D'
        else:
            return robust(history, rng)
    if n == 4:
        if history[1][1] == 'D' and history[2][1] == 'C' and history[3][1] == 'C':
            return 'D'
        else:
            return robust(history, rng)
    if n == 5:
        if history[1][1] == 'D' and history[2][1] == 'C' and history[3][1] == 'C' and history[4][1] == 'D':
            return 'D'
        else:
            return robust(history, rng)
    if n == 6:
        if history[1][1] == 'D' and history[2][1] == 'C' and history[3][1] == 'C' and history[4][1] == 'D' and history[5][1] == 'C':
            return 'D'
        else:
            return robust(history, rng)
    if (history[1][1] == 'D' and history[2][1] == 'C' and history[3][1] == 'C' and
        history[4][1] == 'D' and history[5][1] == 'C'):
        return 'D'
    else:
        return robust(history, rng)
